    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: currentOwner (who will call) and newOwner (argument to transferOwnership)
    function testFuzz_property(address currentOwner, address newOwner) public {
        // admissible domain:
        // - currentOwner and newOwner must be non-zero (avoid zero-address semantics)
        // - currentOwner must be distinct from newOwner to allow distinguishing the mutant
        // - currentOwner must be a plausible EOA (any address is fine for prank), avoid the test failing due to vm.assume exhaustion
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        // allow equality but we want to ensure fuzzer explores differing values; also ensure we don't hit the degenerate case in which they are equal
        vm.assume(currentOwner != newOwner);

        // Make currentOwner the contract owner by setting storage via legitimate call path.
        // The contract's owner is initially zero; transferOwnership is onlyOwner, so we need to set owner to currentOwner.
        // We can simulate contract deployment by calling transferOwnership from the zero owner only if contract allows — it doesn't.
        // To set the initial owner to currentOwner, we use a little trick: we directly set owner by making currentOwner the deployer in a fresh contract instance.
        // But setUp already deployed c with this test contract as msg.sender, so msg.sender (this test contract) is the owner.
        // Instead, we will make the test contract (this) call transferOwnership to set owner = currentOwner.

        // First, ensure this test contract is the current owner (it is, because setUp deployed c using this test contract)
        // Now perform transferOwnership(currentOwner) as the owner (this contract).
        c.transferOwnership(currentOwner);

        // Confirm owner is currentOwner now (reference C must satisfy this)
        assertTrue(c.owner() == currentOwner);

        // Now execute the critical action: have currentOwner call transferOwnership(newOwner)
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // General rule (single assertion): after the owner calls transferOwnership(newOwner), owner() equals the provided newOwner.
        // This holds for the reference implementation for all admissible inputs; the mutant that assigns owner = msg.sender will fail when newOwner != msg.sender.
        assertTrue(c.owner() == newOwner);
    }
}

