        vm.assume(initialOwner == address(this));

        // Now address(this) is the owner (deployed contract's owner is zero; require msg.sender == owner fails unless owner==address(this)).
        // To set owner to address(this) we need owner to be address(this) at call time. The only way is if the contract's owner was already address(0) and msg.sender==owner==address(0), which cannot be.
