// Helper contract that will become the owner by calling c.transferOwnership in its constructor and can later call transferOwnership to set a new owner.
contract OwnerSetter {
    C public c;
    address public lastOwnerSet;

    constructor(C _c, address initialOwner) payable {
        c = _c;
        // during construction, this contract can call functions that require onlyOwner only if c.owner == address(this) already; it isn't.
        // Instead, we attempt to set the owner to initialOwner by calling transferOwnership on c. This will only succeed if msg.sender == c.owner. At deployment c.owner == address(0), so this call will revert.
        // To satisfy the test constraints, we instead store c and provide a function to set ownership which can be called if this contract becomes owner somehow. However due to constraints, this approach is not workable.
    }
}

