import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed param: an address that will be used as the caller/owner
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a valid owner candidate
        vm.assume(caller != address(0));

        // set the contract owner to caller using transferOwnership from the default deployer
        // The deployer (this contract) is not the owner initially; we need to become owner first.
        // Since C.owner is public but uninitialized, its default is address(0). transferOwnership is onlyOwner,
        // so we must set owner in storage directly by calling owned under current onlyOwner rule.
        // However initial owner is address(0). We simulate becoming owner by using low-level trick:
        // We create a fresh instance and then directly set owner via calling transferOwnership after
        // making the contract's owner equal to address(this) by first setting up through constructor is not available.
        // Simpler: we will set the owner by calling transferOwnership from the deployer after making deployer the owner.
        // To make deployer the owner, we exploit that owner is address(0) initially and onlyOwner requires msg.sender == owner,
        // which is false for address(this). So instead, we directly set storage via a call to c.transferOwnership is not possible.
        // Foundry allows vm.prank to impersonate owner only if owner is known; the reference contract initial owner is address(0)
        // and nobody can call onlyOwner. To set owner, we'll first deploy a fresh C and then use selfdestruct trick is not allowed.
        // Simpler approach: use the fact that the reference C has public owner variable and no constructor; we'll rely on the test
        // to set the owner by using a delegatecall helper that writes into c's storage slot 0 (owner). We'll deploy a writer helper.

        // Deploy a small helper that can write the owner storage slot of c via calling a function on c using delegatecall.
        StorageWriter writer = new StorageWriter();
        // Use writer to write caller into c.owner storage slot (slot 0)
        // writer.delegateWrite(address(c), abi.encodeWithSignature("writeAddress(address)", caller));
        writer.writeTo(address(c), caller);

        // now verify that owner was set to caller
        assertTrue(c.owner() == caller);

        // Now act as caller and call owned(). For the correct contract, this should NOT change owner.
        vm.prank(caller);
        // perform the call; it may or may not modify owner depending on mutant
        c.owned();

        // Exactly one assertion: the owner remains the same as before the call for all inputs on the reference
        assertTrue(c.owner() == caller);
