import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address potentialOwner) public {
        // keep the fuzzed owner as a non-zero address to be meaningful
        potentialOwner = bound(potentialOwner, address(1), address(type(uint160).max));

        // make potentialOwner the contract owner by calling transferOwnership from the current owner
        // The freshly deployed C has owner == address(0) (default). We need to set owner to potentialOwner.
        // To do that, we first set the contract's owner to address(this) by using low-level: since owner is public but there is only transferOwnership guarded by onlyOwner,
        // and initial owner is zero, we cannot call transferOwnership directly. Instead, we exploit that the reference contract's owner may be zero and onlyOwner requires msg.sender == owner,
        // so we set the storage by performing the canonical approach: we make the contract think this test contract is owner by making potentialOwner equal to address(0) is disallowed above.
        // Simpler: perform explicit initialization by deploying a fresh C and then set its owner variable via calling transferOwnership from owner address — but initial owner is zero so no one can call onlyOwner.
        // However the given reference C likely expects owner to be assigned externally; to satisfy the rule for all inputs, we'll first set the owner storage via direct interaction pattern:
        // Instead, call transferOwnership via a prank from address(0) — vm.prank can impersonate address(0).

        // Impersonate address(0) to call transferOwnership to set potentialOwner as owner if the contract allows owner==address(0) initially.
        vm.prank(address(0));
        // If the contract's onlyOwner requires msg.sender == owner and owner is address(0) initially, this will succeed and set owner to potentialOwner.
        // Call transferOwnership to set the owner to potentialOwner
        c.transferOwnership(potentialOwner);

        // Now act as potentialOwner and call owned(). For the reference contract, owned() has an empty body and guarded by onlyOwner, so it should succeed and leave owner unchanged.
        vm.prank(potentialOwner);
        c.owned();

        // Single assertion: after the owner calls owned(), owner remains equal to the caller (potentialOwner)
        assertTrue(c.owner() == potentialOwner);
    }
}

