pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an address that will act as caller; the property must hold for ALL callers
    function testFuzz_property(address caller) public {
        // keep the address wide but non-zero to avoid trivial zero-address edge if desired
        vm.assume(caller != address(0));

        // initial owner should be address(0) because C.owner is default-initialized
        address before = c.owner();

        // perform the call as `caller` to the onlyOwner-protected function `owned()`
        // capture whether the call succeeded (reference should require onlyOwner and thus fail unless
        // caller==owner; but regardless of success, the invariant we assert is that owner value
        // after the call equals owner before the call — i.e., guarded calls do not mutate owner.
        bool ok;
        try c.owned{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // NOTE: We must perform the call as the fuzzed caller
        // Do the call under prank so msg.sender is caller. Re-run under prank to actually execute
        // with the desired sender; use low-level approach: vm.prank then call.
        // To ensure the call happened with that sender, we repeat the call under vm.prank and ignore revert.
        vm.prank(caller);
        try c.owned() {
            // no-op
        } catch {
            // ignore revert
        }

        // After driving the contract with caller, read the owner getter.
        address after = c.owner();

        // General invariant: calling an onlyOwner-protected function must NOT change the owner value.
        // The correct contract preserves owner for all callers; the mutant will change owner to caller
        // when the modifier assigns owner = msg.sender, so this assertion will fail for some caller.
        assertTrue(after == before);
    }
}
